package com.bank.ddd.model;

import java.util.logging.Logger;

// ENTITY + AGGREGATE ROOT: identity = accountId, enforces its invariant.
public class Account {
    private static final Logger log = Logger.getLogger(Account.class.getName());
    private final String accountId;           // identity
    private final String holderName;
    private Money balance;                     // mutable state (value object)

    public Account(String accountId, String holderName, Money balance) {
        this.accountId = accountId; this.holderName = holderName; this.balance = balance;
    }
    public void debit(Money amount) {
        if (balance.isLessThan(amount))
            throw new IllegalStateException("Insufficient funds in " + accountId);
        balance = balance.subtract(amount);    // invariant: never negative
        log.info(() -> accountId + " debited, balance=" + balance.amount());
    }
    public void credit(Money amount) {
        balance = balance.add(amount);
        log.info(() -> accountId + " credited, balance=" + balance.amount());
    }
    public String getAccountId() { return accountId; }
    public Money getBalance() { return balance; }
    // Equality by identity, not by fields (it is an Entity).
    @Override public boolean equals(Object o) {
        return o instanceof Account a && a.accountId.equals(accountId);
    }
    @Override public int hashCode() { return accountId.hashCode(); }
}
