package com.bank.ddd.repository;

import com.bank.ddd.model.Account;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

// REPOSITORY: one per aggregate root. In Spring: extends JpaRepository<Account,String>.
public class AccountRepository {
    private final Map<String, Account> store = new HashMap<>();
    public void save(Account account) { store.put(account.getAccountId(), account); }
    public Optional<Account> findById(String id) { return Optional.ofNullable(store.get(id)); }
}
