package com.bank.ddd.domain;

import com.bank.ddd.model.Account;
import com.bank.ddd.model.Money;

// DOMAIN SERVICE: logic that spans entities and belongs to no single one.
public class TransferDomainService {
    public void transfer(Account from, Account to, Money amount) {
        from.debit(amount);   // invariants enforced inside each aggregate root
        to.credit(amount);
    }
}
