package com.bank.ddd.application;

import com.bank.ddd.domain.TransferDomainService;
import com.bank.ddd.event.FundsTransferredEvent;
import com.bank.ddd.model.Account;
import com.bank.ddd.model.Money;
import com.bank.ddd.repository.AccountRepository;
import java.util.logging.Logger;

// APPLICATION SERVICE: orchestrates the use case, manages the transaction,
// calls domain services + repositories. In Spring: @Service @Transactional.
public class TransferApplicationService {
    private static final Logger log = Logger.getLogger(TransferApplicationService.class.getName());
    private final AccountRepository accountRepo;
    private final TransferDomainService transferDomainService;

    public TransferApplicationService(AccountRepository accountRepo, TransferDomainService ds) {
        this.accountRepo = accountRepo; this.transferDomainService = ds;
    }

    public FundsTransferredEvent transfer(String fromId, String toId, Money amount) {
        Account from = accountRepo.findById(fromId)
            .orElseThrow(() -> new IllegalArgumentException("No account " + fromId));
        Account to = accountRepo.findById(toId)
            .orElseThrow(() -> new IllegalArgumentException("No account " + toId));
        transferDomainService.transfer(from, to, amount);   // business rules live below
        accountRepo.save(from);
        accountRepo.save(to);
        FundsTransferredEvent event = new FundsTransferredEvent(fromId, toId, amount);
        log.info(() -> "Published domain event: " + event);
        return event;
    }
}
