package com.bank.ddd;

import com.bank.ddd.application.TransferApplicationService;
import com.bank.ddd.domain.TransferDomainService;
import com.bank.ddd.event.FundsTransferredEvent;
import com.bank.ddd.model.Account;
import com.bank.ddd.model.Money;
import com.bank.ddd.repository.AccountRepository;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class DddDemo {
    private static final Logger log = Logger.getLogger(DddDemo.class.getName());

    public static void main(String[] args) {
        AccountRepository repo = new AccountRepository();
        repo.save(new Account("SAV2001", "Rajesh Kumar", new Money(new BigDecimal("1000000"), "INR")));
        repo.save(new Account("CUR3001", "Priya Sharma", new Money(new BigDecimal("250000"), "INR")));

        TransferApplicationService appService =
            new TransferApplicationService(repo, new TransferDomainService());

        log.info("=== DDD transfer: Value Object + Entity + Repo + Domain + App Service ===");
        Money rentAmount = new Money(new BigDecimal("50000"), "INR");
        FundsTransferredEvent event = appService.transfer("SAV2001", "CUR3001", rentAmount);

        log.info("Rajesh balance: " + repo.findById("SAV2001").get().getBalance().amount());
        log.info("Priya balance: " + repo.findById("CUR3001").get().getBalance().amount());
        log.info("Domain event produced: " + event);
    }
}
